/* Accordion. Sections stacked on one surface, split by hairlines. The panel
   opens with a grid-row transition (0fr to 1fr), so the height animates
   without measuring; reduced motion makes it instant (the global rule). */

.root {
  display: flex;
  flex-direction: column;
  width: var(--accordion-width, min(560px, 100%));
}

.glass {
  overflow: hidden;
  border-radius: var(--accordion-radius, var(--r-lg));
  background: var(--glass-fill-nested);
  -webkit-backdrop-filter: var(--blur-panel-light);
  backdrop-filter: var(--blur-panel-light);
  border: var(--border-w) solid var(--glass-edge);
  box-shadow: var(--shadow-specular), var(--shadow-hairline-card);
}

.item + .item {
  border-top: var(--border-w) solid var(--line-glass);
}

.plain .item {
  border-bottom: var(--border-w) solid var(--line);
}

.plain .item + .item {
  border-top: 0;
}

.heading {
  margin: 0;
  font: inherit;
}

.trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  padding: var(--accordion-pad-y, calc(14px * var(--density))) var(--accordion-pad-x, calc(16px * var(--density)));
  border: 0;
  background: transparent;
  text-align: left;
  font-size: var(--text-body);
  font-weight: 700;
  color: var(--ink-heading);
  transition: background-color var(--dur) var(--ease);
}

.plain .trigger {
  padding-left: 0;
  padding-right: 0;
}

.trigger:hover:not(:disabled) {
  background: var(--wash-hover);
}

.plain .trigger:hover:not(:disabled) {
  background: transparent;
  color: var(--ink-brand);
}

.trigger:focus-visible {
  outline: 2px solid var(--focus-color);
  outline-offset: -2px;
}

.trigger:disabled {
  color: var(--ink-disabled);
  cursor: not-allowed;
}

.title {
  min-width: 0;
}

.chevron {
  flex-shrink: 0;
  color: var(--ink-muted);
  transition: transform var(--dur-slow) var(--ease);
}

.item[data-state="open"] .chevron {
  transform: rotate(180deg);
}

.panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--dur-slow) var(--ease-out);
}

.panel[data-open] {
  grid-template-rows: 1fr;
}

.panelInner {
  min-height: 0;
  overflow: hidden;
}

.content {
  padding: 0 var(--accordion-pad-x, calc(16px * var(--density))) var(--accordion-pad-y, calc(14px * var(--density)));
  font-size: var(--text-small);
  line-height: 1.6;
  color: var(--ink-body);
}

.plain .content {
  padding-left: 0;
  padding-right: 0;
}

"use client";

import { useId, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { cx } from "../_internal/cx";
import { IconChevronDown } from "../Icon/Icon";
import styles from "./Accordion.module.css";

export type AccordionItem = {
  id: string;
  title: ReactNode;
  content: ReactNode;
  disabled?: boolean;
};

export type AccordionProps = {
  items: ReadonlyArray<AccordionItem>;
  /** single = one section open at a time. multiple = any number. */
  type?: "single" | "multiple";
  /** Open ids, controlled. Pair with onValueChange. */
  value?: ReadonlyArray<string>;
  /** Open ids on first render, uncontrolled. */
  defaultValue?: ReadonlyArray<string>;
  onValueChange?: (value: string[]) => void;
  /** single only: false keeps one section open at all times. */
  collapsible?: boolean;
  /** Heading level the triggers sit in, to fit the page outline. */
  headingLevel?: 2 | 3 | 4 | 5;
  /** glass = a frosted panel with hairlines between sections. plain = hairlines only. */
  appearance?: "glass" | "plain";
  className?: string;
};

/**
 * Stacked sections that open and close in place (WAI-ARIA accordion). Each
 * header is a real heading holding a button with aria-expanded and
 * aria-controls; Up and Down move between headers, Home and End jump to the
 * ends. The panel animates its height with a grid row transition, which
 * reduced motion turns off.
 */
export function Accordion({
  items,
  type = "single",
  value,
  defaultValue,
  onValueChange,
  collapsible = true,
  headingLevel = 3,
  appearance = "glass",
  className,
}: AccordionProps) {
  const baseId = useId();
  const [inner, setInner] = useState<string[]>(() => [...(defaultValue ?? [])]);
  const open = value ? [...value] : inner;
  const triggers = useRef<Array<HTMLButtonElement | null>>([]);
  const Heading = `h${headingLevel}` as const;

  const toggle = (id: string) => {
    const isOpen = open.includes(id);
    let next: string[];
    if (type === "single") {
      if (isOpen) next = collapsible ? [] : open;
      else next = [id];
    } else next = isOpen ? open.filter((o) => o !== id) : [...open, id];
    if (!value) setInner(next);
    onValueChange?.(next);
  };

  const onKeyDown = (e: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const enabled = items.map((it, i) => (it.disabled ? -1 : i)).filter((i) => i >= 0);
    const pos = enabled.indexOf(index);
    let target: number | undefined;
    if (e.key === "ArrowDown") target = enabled[(pos + 1) % enabled.length];
    else if (e.key === "ArrowUp") target = enabled[(pos - 1 + enabled.length) % enabled.length];
    else if (e.key === "Home") target = enabled[0];
    else if (e.key === "End") target = enabled[enabled.length - 1];
    if (target === undefined) return;
    e.preventDefault();
    triggers.current[target]?.focus();
  };

  return (
    <div data-slot="accordion" className={cx(styles.root, styles[appearance], className)}>
      {items.map((item, i) => {
        const isOpen = open.includes(item.id);
        const triggerId = `${baseId}-t-${item.id}`;
        const panelId = `${baseId}-p-${item.id}`;
        return (
          <div key={item.id} className={styles.item} data-state={isOpen ? "open" : "closed"}>
            <Heading className={styles.heading}>
              <button
                ref={(el) => {
                  triggers.current[i] = el;
                }}
                type="button"
                id={triggerId}
                className={styles.trigger}
                aria-expanded={isOpen}
                aria-controls={panelId}
                aria-disabled={(type === "single" && isOpen && !collapsible) || undefined}
                disabled={item.disabled}
                onClick={() => toggle(item.id)}
                onKeyDown={(e) => onKeyDown(e, i)}
              >
                <span className={styles.title}>{item.title}</span>
                <IconChevronDown size={16} className={styles.chevron} aria-hidden="true" />
              </button>
            </Heading>
            <div id={panelId} role="region" aria-labelledby={triggerId} className={styles.panel} data-open={isOpen || undefined}>
              <div className={styles.panelInner} inert={!isOpen}>
                <div className={styles.content}>{item.content}</div>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}
